        while ( bb.hasRemaining() ) {
            if ( ( bb.get( i ) & 0x80 ) == 0 ) { // 1-byte character
                sb.append( ( char ) ( bb.get( i ) & 0x7F ) );
                i++;
            } else if ( ( bb.get( i ) & 0xE0 ) == 0xC0 ) { // 2-byte character
                if ( bb.remaining() < 2 ) break;
                sb.append( ( char ) ( ( ( bb.get( i ) & 0x1F ) << 6 ) | ( bb.get( i + 1 ) & 0x3F ) ) );
                i += 2;
            } else if ( ( bb.get( i ) & 0xF0 ) == 0xE0 ) { // 3-byte character
                if ( bb.remaining() < 3 ) break;
                sb.append( ( char ) ( ( ( bb.get( i ) & 0x0F ) << 12 ) | ( ( bb.get( i + 1 ) & 0x3F ) << 6 ) | ( bb.get( i + 2 ) & 0x3F ) ) );
                i += 3;
            } else if ( ( bb.get( i ) & 0xF8 ) == 0xF0 ) { // 4-byte character
                if ( bb.remaining() < 4 ) break;
                int codePoint = ( ( ( bb.get( i ) & 0x07 ) << 18 ) | ( ( bb.get( i + 1 ) & 0x3F ) << 12 ) | ( ( bb.get( i + 2 ) & 0x3F ) << 6 ) | ( bb.get( i + 3 ) & 0x3F ) );
                sb.append( Character.toChars( codePoint ) );
                i += 4;
            } else {
                throw new IllegalArgumentException( "Invalid UTF-8 sequence" );
            }
        }
        return i;
    } catch ( BufferUnderflowException e ) {
        throw new IllegalArgumentException( "ByteBuffer is not fully readable", e );
