    // Create vertices and add them to their respective sets based on resultMap
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("setA_")) {
            setA.add(entry.getValue());
        } else if (entry.getKey().startsWith("setB_")) {
            setB.add(entry.getValue());
        }
