Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType, new HashMap<>());

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArgument = actualTypeArguments[i];
        resolvedArguments[i] = resolveRawClass(typeArgument, typeVariableMap);
        if (resolvedArguments[i] == null) {
            return null; // Unable to resolve all arguments
        }
    }

    return resolvedArguments;
}

private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType, Map<TypeVariable<?>, Type> typeVariableMap) {
    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<?>[] typeVariables = targetType.getSuperclass().getTypeParameters();
        for (int i = 0; i < actualTypeArguments.length; i++) {
            typeVariableMap.put(typeVariables[i], actualTypeArguments[i]);
        }
        getTypeVariableMap(targetType.getSuperclass(), typeVariableMap);
    }

    for (Type genericInterface : targetType.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericInterface;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
            for (int i = 0; i < actualTypeArguments.length; i++) {
                typeVariableMap.put(typeVariables[i], actualTypeArguments[i]);
            }
            getTypeVariableMap((Class<?>) parameterizedType.getRawType(), typeVariableMap);
        }
    }

    return typeVariableMap;
}

private static Class<?> resolveRawClass(Type type, Map<TypeVariable<?>, Type> typeVariableMap) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof TypeVariable<?>) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        Type boundType = typeVariableMap.get(typeVariable);
        return resolveRawClass(boundType, typeVariableMap);
    } else if (type instanceof ParameterizedType) {
        return resolveRawClass(((ParameterizedType) type).getRawType(), typeVariableMap);
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (upperBounds.length > 0) {
            return resolveRawClass(upperBounds[0], typeVariableMap);
        }
        Type[] lowerBounds = wildcardType.getLowerBounds();
        if (lowerBounds.length > 0) {
            return resolveRawClass(lowerBounds[0], typeVariableMap);
        }
    }

    return null; // Unable to resolve type
}

