static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the day of the month aligned to dayStep
        day = ((day - 1) / dayStep * dayStep) + 1;

        // Ensure day is within the month bounds
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid day calculated: " + day);
        }

        return year * 10000 + month * 100 + day;
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid timeBucket or dayStep: " + timeBucket + ", " + dayStep, e);
    }
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            if (i + 1 < index + len && Character.isSurrogatePair(ch, str.charAt(i + 1))) {
                size += 4;
                i++; // Skip the next surrogate as it is already counted
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair in CharSequence");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

