List<PathSegmentImpl> function ( URI u , boolean decode ) { 
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if ( u == null ) {
        return pathSegments;
    }
    String path = u.getRawPath();
    if ( path == null || path.isEmpty() ) {
        return pathSegments;
    }
    if ( path.startsWith("/") ) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for ( String segment : segments ) {
        String decodedSegment = decode ? decodeURIComponent(segment) : segment;
        pathSegments.add(new PathSegmentImpl(decodedSegment, false));
    }
    return pathSegments;
}

