void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    char type = descriptor.charAt(0);
    if (type == '(') { // Method descriptor
        int currentPos = 1;
        while (descriptor.charAt(currentPos) != ')') {
            type = descriptor.charAt(currentPos);
            currentPos += popType(type, descriptor, currentPos);
        }
    } else { // Type descriptor
        popType(type, descriptor, 0);
    }
}

private int popType(char type, final String descriptor, int pos) {
    switch (type) {
        case 'B':
        case 'C':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
            // These are single-word types
            pos++;
            break;
        case 'D':
        case 'J':
            // These are double-word types
            pos++;
            break;
        case 'L':
            // Object type; skip till ';'
            while (descriptor.charAt(pos) != ';') {
                pos++;
            }
            pos++; // skip ';'
            break;
        case '[':
            // Array type; skip to next type
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            pos += popType(descriptor.charAt(pos), descriptor, pos);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor type: " + type);
    }
    return pos;
}

