String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'b':
                    output.append('\b');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                default:
                    throw new Exception("Invalid escape sequence '\\" + nextChar + "'");
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

